(function(){
  var KEEP=/^(data-|aria-)/;
  var SPECIAL={'class':'className','for':'htmlFor','tabindex':'tabIndex','readonly':'readOnly',
               'maxlength':'maxLength','colspan':'colSpan','rowspan':'rowSpan','usemap':'useMap',
               'contenteditable':'contentEditable','crossorigin':'crossOrigin','datetime':'dateTime',
               'enctype':'encType','autofocus':'autoFocus','autocomplete':'autoComplete',
               'srcset':'srcSet','novalidate':'noValidate','accept-charset':'acceptCharset'};
  var VOID={path:1,circle:1,rect:1,line:1,polyline:1,polygon:1,ellipse:1,use:1,stop:1,image:1,
            br:1,img:1,input:1,hr:1,meta:1,link:1,area:1,base:1,col:1,embed:1,source:1,track:1,wbr:1};
  function camel(name){
    if(KEEP.test(name)) return name;
    if(SPECIAL[name.toLowerCase()]) return SPECIAL[name.toLowerCase()];
    return name.replace(/[:-]+([a-zA-Z0-9])/g,function(m,c){return c.toUpperCase();});
  }
  function styleObj(s){
    var parts=String(s).split(';'),o=[];
    for(var i=0;i<parts.length;i++){
      var p=parts[i];
      if(!p||p.indexOf(':')<0) continue;
      var k=p.slice(0,p.indexOf(':')).trim(),v=p.slice(p.indexOf(':')+1).trim();
      if(!k) continue;
      var ck=(k.charAt(0)==='-')?k:k.replace(/-+([a-z])/g,function(m,c){return c.toUpperCase();});
      o.push((/^[A-Za-z][A-Za-z0-9]*$/.test(ck)?ck:JSON.stringify(ck))+": '"+v.replace(/'/g,"\\'")+"'");
    }
    return '{{'+o.join(', ')+'}}';
  }
  var ATTR_RE=/([^\s=\/>]+)(\s*=\s*("[^"]*"|'[^']*'|[^\s"'>]+))?/g;
  function convAttrs(raw,spread){
    var out=[],m;
    ATTR_RE.lastIndex=0;
    while((m=ATTR_RE.exec(raw))){
      var name=m[1],val=m[3];
      if(!name) continue;
      if(val==null){ out.push(camel(name)); continue; }
      var q=val.charAt(0),body=(q==='"'||q==="'")?val.slice(1,-1):val;
      if(name.toLowerCase()==='style'){ out.push('style='+styleObj(body)); continue; }
      out.push(camel(name)+'="'+body.replace(/"/g,'&quot;')+'"');
    }
    if(spread) out.push('{...props}');
    return out.length?(' '+out.join(' ')):'';
  }
  function clean(svg){
    return String(svg||'')
      .replace(/<\?xml[\s\S]*?\?>/g,'')
      .replace(/<!DOCTYPE[\s\S]*?>/gi,'')
      .replace(/<!--[\s\S]*?-->/g,'')
      .replace(/^\s+|\s+$/g,'');
  }
  function transform(svg,opt){
    opt=opt||{};
    var s=clean(svg);
    if(!s) return {error:'请输入 SVG 源码'};
    if(s.indexOf('<svg')<0) return {error:'未找到 svg 根元素'};
    var first=true;
    var out=s.replace(/<(\/?)([A-Za-z][\w:.-]*)((?:\s+[^\s=\/>]+(?:\s*=\s*(?:"[^"]*"|'[^']*'|[^\s"'>]+))?)*)\s*(\/?)>/g,
      function(all,slash,tag,attrs,selfc){
        if(slash) return '</'+tag+'>';
        var spread=(first&&opt.spread!==false&&tag.toLowerCase()==='svg');
        var a=convAttrs(attrs||'',spread);
        if(first) first=false;
        var sc=(selfc==='/')||VOID[tag.toLowerCase()]===1;
        return '<'+tag+a+(sc?' />':'>');
      });
    var name=String(opt.name||'Icon').replace(/[^A-Za-z0-9_]/g,'')||'Icon';
    if(/^[0-9]/.test(name)) name='Icon'+name;
    var body=out.split('\n').map(function(l){return l?('    '+l):l;}).join('\n');
    var ts=!!opt.ts;
    var sig=ts?('const '+name+' = (props: React.SVGProps<SVGSVGElement>) => (')
              :('const '+name+' = (props) => (');
    var code="import * as React from 'react';\n\n"+sig+'\n'+body+'\n);\n\nexport default '+name+';\n';
    if(opt.wrap===false) code=out+'\n';
    var attrCount=(out.match(/[A-Za-z]+="/g)||[]).length;
    return {value:{code:code,jsx:out,name:name,attrs:attrCount,bytes:code.length}};
  }
  var API={transform:transform,camel:camel,styleObj:styleObj,clean:clean};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__JsxForge__=API;
})();
